import os
import csv
from argparse import ArgumentParser

from accloadtant import load_data

FILE_TYPE_MAPPING = {
    "csv": "CSVServiceCost"
}

parser = ArgumentParser("accloadtant")
parser.add_argument("file", type=str, help='Billing file to load')
args = parser.parse_args()

if __name__ == "__main__":
    _, file_extension = os.path.splitext(args.file)
    file_extension = FILE_TYPE_MAPPING.get(file_extension.lower())

    usage = load_data(args.file, file_extension)

    print("Simple Storage Service")
    for area, concepts in usage.totals(omit=lambda x: x.is_data_transfer or x.type == "StorageObjectCount"):
        print("\t", area)
        for c, v, u in concepts:
            print("\t\t{}\t{} {}".format(c, v, u))

    data_transfers = usage.data_transfers()
    if len(data_transfers) > 0:
        print("Data Transfer")
        for area, concepts in data_transfers.totals(omit=lambda x: not x.is_data_transfer):
            print("\t", area)
            for c, v, u in concepts:
                print("\t\t{}\t{} {}".format(c, v, u))

